pub const DECIMALS: u8 = 18;
/// 1,000,000,000 tokens, all minted to the contract as pool inventory.
pub const INITIAL_SUPPLY: u128 = 1_000_000_000 * 10u128.pow(DECIMALS as u32);

/// Capital rules from docs/SPEC.md "Mechanics & locked parameters".
/// Ratios are in basis points (10_000 = 100% or 1.0x), durations in seconds.
#[near(serializers = [borsh, json])]
#[derive(Clone, Debug, PartialEq)]
pub struct Params {
    pub pool_fee_bps: u32,
    pub treasury_fee_bps: u32,
    pub creator_fee_bps: u32,
    pub issuance_mnav_bps: u32,
    pub max_issuance_bps_per_epoch: u32,
    pub epoch_secs: u64,
    pub buyback_mnav_bps: u32,
    pub redemption_mnav_bps: u32,
    pub cash_buffer_bps: u32,
    pub cash_refill_bps: u32,
    pub twap_window_secs: u64,
    pub oracle_max_age_secs: u64,
    pub rebalance_cooldown_secs: u64,
    pub caller_tip_bps: u32,
    pub target_leverage_bps: u32,
}

impl Default for Params {
    fn default() -> Self {
        Self {
            pool_fee_bps: 100,
            treasury_fee_bps: 80,
            creator_fee_bps: 20,
            issuance_mnav_bps: 20_000,
            max_issuance_bps_per_epoch: 100,
            epoch_secs: 24 * 3600,
            buyback_mnav_bps: 10_000,
            redemption_mnav_bps: 9_000,
            cash_buffer_bps: 2_000,
            cash_refill_bps: 1_000,
            twap_window_secs: 30 * 60,
            oracle_max_age_secs: 15 * 60,
            rebalance_cooldown_secs: 3600,
            caller_tip_bps: 5,
            target_leverage_bps: 10_000,
        }
    }
}

/// The thesis stock's token on one treasury chain.
#[near(serializers = [borsh, json])]
#[derive(Clone, Debug, PartialEq)]
pub struct Venue {
    /// An `EvmChain::name` from the chains config.
    pub chain: String,
    /// ERC-20 address, `0x` + 40 hex characters.
    pub token: String,
    pub decimals: u8,
}

/// The thesis stock: its oracle feed on NEAR and its token on each treasury chain.
/// Fixed by the factory from its immutable list, never chosen freely by a creator.
#[near(serializers = [borsh, json])]
#[derive(Clone, Debug, PartialEq)]
pub struct Stock {
    /// e.g. "NVDA"
    pub ticker: String,
    /// Oracle price feed ID, 64 lowercase hex characters without `0x`. One global
    /// price per stock values the holdings on every chain.
    pub price_id: String,
    pub venues: Vec<Venue>,
}

impl Stock {
    pub fn assert_valid(&self, chains: &ChainsConfig) {
        require!(
            self.price_id.len() == 64
                && self
                    .price_id
                    .bytes()
                    .all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')),
            "price_id must be 64 lowercase hex characters"
        );
        require!(
            !self.ticker.is_empty() && self.ticker.len() <= 10,
            "Invalid ticker"
        );
        require!(!self.venues.is_empty(), "List at least one venue");
        for (i, v) in self.venues.iter().enumerate() {
            require!(
                chains.index(&v.chain).is_some(),
                "Venue chain is not in the chains config"
            );
            require!(
                self.venues[..i].iter().all(|w| w.chain != v.chain),
                "One venue per chain"
            );
            parse_address(&v.token);
            // Keeps 10^(decimals + 18) inside u128 in the value math.
            require!(v.decimals <= 18, "Stock decimals must be at most 18");
        }
    }
}

#[near(serializers = [json])]
pub struct MemeInfo {
    pub creator: AccountId,
    pub usdc: AccountId,
    pub oracle: AccountId,
    pub stock: Stock,
}

#[derive(BorshStorageKey)]
#[near]
pub(crate) enum StorageKey {
    Token,
    Claimable,
    SignedTxs,
    CreditedCash,
}

#[near(contract_state)]
#[derive(PanicOnDefault)]
pub struct Meme {
    token: FungibleToken,
    metadata: FungibleTokenMetadata,
    creator: AccountId,
    usdc: AccountId,
    /// Pyth contract, e.g. `pyth-oracle.near`.
    oracle: AccountId,
    stock: Stock,
    params: Params,
    /// USDC side of the internal pool. The meme side is this contract's own token balance.
    usdc_reserve: u128,
    /// USDC cash owned by the treasury (fees for now; buffer for buybacks later).
    treasury_usdc: u128,
    /// USDC owed to an account: creator fees and payouts whose transfer failed.
    claimable: LookupMap<AccountId, u128>,
    twap: Twap,
    engine: Engine,
    chains: ChainsConfig,
    treasury: Treasury,
}

#[near]
impl Meme {
    /// Called once by the factory in the same batch that deploys the code.
    #[init]
    pub fn new(
        creator: AccountId,
        usdc: AccountId,
        oracle: AccountId,
        stock: Stock,
        chains: ChainsConfig,
        name: String,
        symbol: String,
        icon: Option<String>,
    ) -> Self {
        chains.assert_valid();
        stock.assert_valid(&chains);
        let metadata = FungibleTokenMetadata {
            spec: FT_METADATA_SPEC.to_string(),
            name,
            symbol,
            icon,
            reference: None,
            reference_hash: None,
            decimals: DECIMALS,
        };
        metadata.assert_valid();

        let mut this = Self {
            token: FungibleToken::new(StorageKey::Token),
            metadata,
            creator,
            usdc,
            oracle,
            stock,
            params: Params::default(),
            usdc_reserve: 0,
            treasury_usdc: 0,
            claimable: LookupMap::new(StorageKey::Claimable),
            twap: Twap::default(),
            engine: Engine::default(),
            treasury: Treasury::new(chains.evm.len()),
            chains,
        };
        let pool = env::current_account_id();
        this.token.internal_register_account(&pool);
        this.token.internal_deposit(&pool, INITIAL_SUPPLY);
        FtMint {
            owner_id: &pool,
            amount: U128(INITIAL_SUPPLY),
            memo: Some("initial pool inventory"),
        }
        .emit();
        this
    }

    pub fn get_params(&self) -> Params {
        self.params.clone()
    }

    pub fn get_info(&self) -> MemeInfo {
        MemeInfo {
            creator: self.creator.clone(),
            usdc: self.usdc.clone(),
            oracle: self.oracle.clone(),
            stock: self.stock.clone(),
        }
    }
}

#[near]
impl FungibleTokenCore for Meme {
    #[payable]
    fn ft_transfer(&mut self, receiver_id: AccountId, amount: U128, memo: Option<String>) {
        self.token.ft_transfer(receiver_id, amount, memo)
    }

    #[payable]
    fn ft_transfer_call(
        &mut self,
        receiver_id: AccountId,
        amount: U128,
        memo: Option<String>,
        msg: String,
    ) -> PromiseOrValue<U128> {
        self.token.ft_transfer_call(receiver_id, amount, memo, msg)
    }

    fn ft_total_supply(&self) -> U128 {
        self.token.ft_total_supply()
    }

    fn ft_balance_of(&self, account_id: AccountId) -> U128 {
        self.token.ft_balance_of(account_id)
    }
}

#[near]
impl FungibleTokenResolver for Meme {
    #[private]
    fn ft_resolve_transfer(
        &mut self,
        sender_id: AccountId,
        receiver_id: AccountId,
        amount: U128,
    ) -> U128 {
        let (used, _burned) =
            self.token
                .internal_ft_resolve_transfer(&sender_id, receiver_id, amount);
        used.into()
    }
}

#[near]
impl StorageManagement for Meme {
    #[payable]
    fn storage_deposit(
        &mut self,
        account_id: Option<AccountId>,
        registration_only: Option<bool>,
    ) -> StorageBalance {
        self.token.storage_deposit(account_id, registration_only)
    }

    #[payable]
    fn storage_withdraw(&mut self, amount: Option<NearToken>) -> StorageBalance {
        self.token.storage_withdraw(amount)
    }

    #[payable]
    fn storage_unregister(&mut self, force: Option<bool>) -> bool {
        self.token.internal_storage_unregister(force).is_some()
    }

    fn storage_balance_bounds(&self) -> StorageBalanceBounds {
        self.token.storage_balance_bounds()
    }

    fn storage_balance_of(&self, account_id: AccountId) -> Option<StorageBalance> {
        self.token.storage_balance_of(account_id)
    }
}

#[near]
impl FungibleTokenMetadataProvider for Meme {
    fn ft_metadata(&self) -> FungibleTokenMetadata {
        self.metadata.clone()
    }
}

