/// The testnet config of contracts/deploy-testnet.sh: Base Sepolia (USDC 6 dp, cash proven
/// by MPC) and Robinhood Chain testnet (USDC 18 dp, cash reported by the relayer).
#[cfg(test)]
pub(crate) fn test_chains() -> ChainsConfig {
    use crate::cash::{CashProof, Finality};
    use crate::treasury::EvmChain;
    ChainsConfig {
        mpc: "v1.signer-prod.testnet".parse().unwrap(),
        bridge: "keeper.solidon.testnet".parse().unwrap(),
        relayer: "keeper.solidon.testnet".parse().unwrap(),
        evm: vec![
            EvmChain {
                name: "base".into(),
                chain_id: 84532,
                usdc: "0x036CbD53842c5426634e7929541eC2318f3dCF7e".into(),
                usdc_decimals: 6,
                swap_router: "0x94cC0AaC535CCDB3C01d6787D6413C739ae12bc4".into(),
                pool_fee: 3000,
                max_fee_per_gas: U128(100_000_000),
                max_priority_fee_per_gas: U128(1_000_000),
                max_swap_usdc: U128(5 * 10u128.pow(6)),
                proof: CashProof::Mpc {
                    foreign_chain: "Base".into(),
                    finality: Finality::Latest,
                },
            },
            EvmChain {
                name: "robinhood".into(),
                chain_id: 46630,
                usdc: "0xbf4479C07Dc6fdc6dAa764A0ccA06969e894275F".into(),
                usdc_decimals: 18,
                swap_router: "0x3ce954107b1a675826b33bf23060dd655e3758fe".into(),
                pool_fee: 3000,
                max_fee_per_gas: U128(100_000_000),
                max_priority_fee_per_gas: U128(10_000_000),
                max_swap_usdc: U128(5 * 10u128.pow(18)),
                proof: CashProof::Relayer,
            },
        ],
    }
}

#[cfg(test)]
pub(crate) fn test_meme(creator: AccountId) -> Meme {
    Meme::new(
        creator,
        "usdc.near".parse().unwrap(),
        "pyth-oracle.near".parse().unwrap(),
        nvda(),
        test_chains(),
        "Nvidia Meme".into(),
        "NVDA".into(),
        None,
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use near_sdk::test_utils::{accounts, VMContextBuilder};
    use near_sdk::testing_env;

    fn setup() -> Meme {
        testing_env!(VMContextBuilder::new()
            .current_account_id("nvda.solidon.near".parse().unwrap())
            .build());
        test_meme(accounts(1))
    }

    #[test]
    fn mints_initial_supply_to_pool() {
        let m = setup();
        assert_eq!(m.ft_total_supply().0, INITIAL_SUPPLY);
        assert_eq!(
            m.ft_balance_of("nvda.solidon.near".parse().unwrap()).0,
            INITIAL_SUPPLY
        );
        assert_eq!(m.ft_balance_of(accounts(1)).0, 0);
    }

    #[test]
    fn metadata_and_info() {
        let m = setup();
        let md = m.ft_metadata();
        assert_eq!((md.symbol.as_str(), md.decimals), ("NVDA", 18));
        let info = m.get_info();
        assert_eq!(info.creator, accounts(1));
        assert_eq!(info.stock, nvda());
        assert_eq!(info.oracle.as_str(), "pyth-oracle.near");
    }

    #[test]
    #[should_panic(expected = "price_id must be 64 lowercase hex")]
    fn rejects_a_bad_price_id() {
        let _ = setup();
        let mut stock = nvda();
        stock.price_id = "0xb107".into();
        Meme::new(
            accounts(1),
            "usdc.near".parse().unwrap(),
            "pyth-oracle.near".parse().unwrap(),
            stock,
            test_chains(),
            "X".into(),
            "X".into(),
            None,
        );
    }

    #[test]
    #[should_panic(expected = "Venue chain is not in the chains config")]
    fn rejects_a_venue_on_an_unlisted_chain() {
        let _ = setup();
        let mut stock = nvda();
        stock.venues[1].chain = "bsc".into();
        stock.assert_valid(&test_chains());
    }

    #[test]
    #[should_panic(expected = "One venue per chain")]
    fn rejects_two_venues_on_one_chain() {
        let _ = setup();
        let mut stock = nvda();
        stock.venues[1].chain = "base".into();
        stock.assert_valid(&test_chains());
    }

    #[test]
    fn params_match_spec() {
        let p = setup().get_params();
        assert_eq!(p.pool_fee_bps, p.treasury_fee_bps + p.creator_fee_bps);
        assert_eq!(
            (p.pool_fee_bps, p.treasury_fee_bps, p.creator_fee_bps),
            (100, 80, 20)
        );
        assert_eq!(
            (
                p.issuance_mnav_bps,
                p.buyback_mnav_bps,
                p.redemption_mnav_bps
            ),
            (20_000, 10_000, 9_000)
        );
        assert_eq!((p.max_issuance_bps_per_epoch, p.epoch_secs), (100, 86_400));
        assert_eq!((p.cash_buffer_bps, p.cash_refill_bps), (2_000, 1_000));
        assert_eq!(
            (
                p.twap_window_secs,
                p.oracle_max_age_secs,
                p.rebalance_cooldown_secs
            ),
            (1_800, 900, 3_600)
        );
        assert_eq!((p.caller_tip_bps, p.target_leverage_bps), (5, 10_000));
    }
}
